import re

PATH = 'unpacked/word/document.xml'
xml = open(PATH, encoding='utf-8').read()

HEADLINES = {
    'EXECUTIVE SUMMARY',
    'FINANCIAL HIGHLIGHTS',
    'REVENUE BREAKDOWN BY SEGMENT',
    'KEY PERFORMANCE INDICATORS',
    'OPERATING EXPENSES',
    'Q1 2025 OUTLOOK',
    'RISK FACTORS',
}

def para_text(p):
    return ''.join(re.findall(r'<w:t[^>]*>([^<]*)</w:t>', p))

def underline_runs(p):
    def fix_run(r):
        # insert <w:u w:val="single"/> into the run's rPr (or add rPr)
        m = re.search(r'<w:rPr>.*?</w:rPr>', r, re.S)
        if m:
            if '<w:u ' not in m.group(0) and '<w:u/>' not in m.group(0):
                new_rpr = m.group(0).replace('</w:rPr>', '<w:u w:val="single"/></w:rPr>')
                return r[:m.start()] + new_rpr + r[m.end():]
            return r
        # no rPr: add one right after the run start tag
        m2 = re.match(r'(<w:r\b[^>]*>)', r)
        if m2:
            return r[:m2.end()] + '<w:rPr><w:u w:val="single"/></w:rPr>' + r[m2.end():]
        return r
    return re.sub(r'<w:r\b[^>]*>.*?</w:r>', lambda mm: fix_run(mm.group(0)), p, flags=re.S)

# split into paragraphs, keeping every piece intact
parts = re.split(r'(<w:p\b[^>]*>.*?</w:p>)', xml, flags=re.S)
count = 0
for i, part in enumerate(parts):
    if part.startswith('<w:p'):
        if para_text(part).strip() in HEADLINES:
            parts[i] = underline_runs(part)
            count += 1

xml2 = ''.join(parts)
open(PATH, 'w', encoding='utf-8').write(xml2)
print('underlined paragraphs:', count)
